    <div
      {...propsRest}
      className={cx(
        'bk',
        [cl[`bk-tabs--${variant}`]],
        [cl[`bk-tabs--${orientation}`]],
        { [cl['bk-tabs']]: !unstyled },
        propsRest.className,
