export const Accordion = Object.assign(
  (props: AccordionProps) => {
    const { unstyled = false, exclusive = true, ...propsRest } = props;

    const name = `bk-accordion-${React.useId()}`;
    const context: AccordionContext = React.useMemo(() => {
      if (exclusive) {
